      document.getElementById('budget-rows').innerHTML=budgets.map(b=>{const spend=tx.filter(t=>t.direction==='expense'&&t.status==='Paid'&&t.category===b.category&&t.period===b.period&&(!b.departmentId||t.departmentId===b.departmentId)).reduce((a,t)=>a+Number(t.amount||0),0);const amount=Number(b.amount)||0,remaining=amount-spend,pct=amount>0?Math.round(spend/amount*100):0,bar=Math.min(100,Math.max(0,pct));const state=remaining<0?'over':pct>=80?'near':'ok';return `<tr><td>${esc(b.period)}</td><td>${esc(b.departmentId?(DB.find('departments',b.departmentId)||{}).name||'Department':'Institution-wide')}</td><td>${esc(b.category)}</td><td>${naira(amount)}</td><td>${naira(spend)}</td><td><strong class="${state==='over'?'budget-over':state==='near'?'budget-near':''}">${remaining<0?'Over by ':''}${naira(Math.abs(remaining))}</strong></td><td><div class="budget-usage"><div class="budget-usage-track" role="progressbar" aria-label="${esc(b.category)} budget utilisation" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,pct)}"><span class="${state}" style="width:${bar}%"></span></div><small class="${state==='over'?'budget-over':state==='near'?'budget-near':''}">${pct}% used</small></div></td></tr>`}).join('')||'<tr><td colspan="7">No budgets defined yet.</td></tr>';
