      let debitTotal=0,creditTotal=0;
      document.getElementById('trial-balance-rows').innerHTML=reportAccounts.map(a=>{const t=totals.get(a.id),net=t.debit-t.credit,debit=net>0?net:0,credit=net<0?-net:0;debitTotal+=debit;creditTotal+=credit;return `<tr><td>${esc(a.code)}</td><td>${esc(a.name)}${a.active===false?' (Inactive)':''}</td><td>${esc(a.type)}</td><td class="num">${naira(debit)}</td><td class="num">${naira(credit)}</td></tr>`;}).join('');
