      document.getElementById('tb-debit').textContent=naira(debitTotal);document.getElementById('tb-credit').textContent=naira(creditTotal);document.getElementById('tb-status').textContent=malformed.length?`Warning: ${malformed.length} journal entr${malformed.length===1?'y is':'ies are'} unbalanced or reference invalid accounts. Review the journal before relying on this report.`:Math.abs(debitTotal-creditTotal)<0.5?'Balanced for journal entries currently posted.':'Warning: trial balance does not balance; review account mappings and journal records.';
