      entries.forEach(j=>{const lines=j.lines||[{accountId:j.debitAccountId,side:'Debit',amount:j.amount},{accountId:j.creditAccountId,side:'Credit',amount:j.amount}];lines.forEach(l=>{const t=map.get(l.accountId);if(t&&l.side==='Debit')t.debit+=Number(l.amount||0);if(t&&l.side==='Credit')t.credit+=Number(l.amount||0);});});
