    document.getElementById('f-coa').onsubmit=e=>{e.preventDefault();const code=document.getElementById('coa-code').value.trim(),name=document.getElementById('coa-name').value.trim(),type=document.getElementById('coa-type').value,normalBalance=document.getElementById('coa-normal').value;if(!code||!name)return UI.toast('Enter an account code and name.','bad');if(DB.get('chartOfAccounts').some(a=>String(a.code).toLowerCase()===code.toLowerCase()))return UI.toast('That account code already exists.','bad');const expected=['Asset','Expense'].includes(type)?'Debit':'Credit';if(normalBalance!==expected&&!confirm(`${type} accounts normally have a ${expected.toLowerCase()} balance. Add this account with ${normalBalance.toLowerCase()} as its normal balance anyway?`))return;DB.insert('chartOfAccounts',{id:DB.uid('COA'),code,name,type,normalBalance,system:false,active:true,createdBy:me.id,createdAt:new Date().toISOString()});DB.log(me.name,`Added chart of accounts ${code} ${name}`);UI.toast('Account added.','ok');finance();};
