    document.getElementById('export-trial-balance').onclick=()=>{const accounts=DB.get('chartOfAccounts'),entries=DB.get('journalEntries'),rows=[['Code','Account','Type','Debit balance NGN','Credit balance NGN']];let dr=0,cr=0;accounts.forEach(a=>{let d=0,c=0;entries.forEach(j=>{const lines=j.lines||[{accountId:j.debitAccountId,side:'Debit',amount:j.amount},{accountId:j.creditAccountId,side:'Credit',amount:j.amount}];lines.forEach(l=>{if(l.accountId===a.id){if(l.side==='Debit')d+=Number(l.amount||0);if(l.side==='Credit')c+=Number(l.amount||0)}})});const net=d-c,db=net>0?net:0,cb=net<0?-net:0;dr+=db;cr+=cb;rows.push([a.code,a.name,a.type,db,cb]);});rows.push(['','','TOTAL',dr,cr]);const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF',csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='pci-trial-balance.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);DB.log(me.name,'Exported trial balance');};
    document.getElementById('f-fin-transaction').onsubmit=e=>{e.preventDefault();const amount=Number(document.getElementById('ft-amount').value),reference=document.getElementById('ft-reference').value.trim(),description=document.getElementById('ft-description').value.trim();if(!Number.isSafeInteger(amount)||amount<=0)return UI.toast('Enter a positive whole-naira amount.','bad');if(!reference||!description||!document.getElementById('ft-period').value.trim())return UI.toast('Reference, description and budget period are required.','bad');if(DB.get('financeTransactions').some(t=>t.reference.toLowerCase()===reference.toLowerCase()))return UI.toast('That transaction reference already exists.','bad');const record={id:DB.uid('FT'),direction:document.getElementById('ft-direction').value,category:document.getElementById('ft-category').value,amount,date:document.getElementById('ft-date').value,period:document.getElementById('ft-period').value.trim(),departmentId:document.getElementById('ft-dept').value||null,reference,description,status:'Pending review',createdBy:me.id,createdAt:new Date().toISOString()};DB.insert('financeTransactions',record);DB.log(me.name,`Created pending ${record.direction} transaction ${reference} (${naira(amount)})`);UI.toast('Transaction saved for review.','ok');finance();};
    document.getElementById('f-payroll').onsubmit=e=>{e.preventDefault();const gross=Number(document.getElementById('payroll-gross').value),deductions=Number(document.getElementById('payroll-deductions').value),allowances=Number(document.getElementById('payroll-allowances').value),period=document.getElementById('payroll-period').value.trim();if(!Number.isSafeInteger(gross)||gross<=0||!Number.isSafeInteger(deductions)||deductions<0||!Number.isSafeInteger(allowances)||allowances<0||deductions>gross+allowances)return UI.toast('Check salary, allowance and deduction amounts.','bad');if(!period)return UI.toast('Enter a pay period.','bad');const status=document.getElementById('payroll-status').value;const rec={id:DB.uid('PAY'),staffId:document.getElementById('payroll-staff').value,period,gross,deductions,allowances,net:gross+allowances-deductions,status,createdBy:me.id,createdAt:new Date().toISOString()};DB.insert('payroll',rec);DB.log(me.name,`Created payroll record for ${period} (${naira(rec.net)} net), status ${status}`);UI.toast('Payroll record saved.','ok');finance();};
