    document.getElementById('export-fee-ledger').onclick = () => {
      const rows = drawFeeLedger(); const data = [['Matric number','Student','Faculty','Department','Level','Fee category','Total fees NGN','Paid NGN','Balance NGN','Status','Percent paid'], ...rows.map(({s,f,d}) => [s.matNo,s.name,facName(d.facultyId),deptName(s.departmentId),s.level,f.fee?(f.fee.level||'All levels'):'No fee structure',f.total,f.paid,f.balance,f.label,f.percent])];
      const csv = data.map(row => row.map(v => `"${String(v ?? '').replace(/"/g,'""')}"`).join(',')).join('\r\n'); const blob = new Blob(['\uFEFF',csv],{type:'text/csv;charset=utf-8;'}); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=`pci-fee-status-${DB.CONFIG.session.replace('/','-')}.csv`; a.click(); URL.revokeObjectURL(url); DB.log(me.name,`Exported ${rows.length} filtered student fee records`); UI.toast('Filtered fee status exported.','ok');
    };
    drawFeeLedger();

    document.getElementById('f-fee').onsubmit = (e) => {
      e.preventDefault();
      const id = document.getElementById('fee-id').value;
      const facultyId = facultySelect.value;
      const levelValue = document.getElementById('fee-level').value;
      const level = levelValue === 'all' ? null : Number(levelValue);
      const sessionValue = document.getElementById('fee-session').value.trim();
      const rawItems = document.getElementById('fee-items').value.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
      if (!facultyId || sessionValue.length < 4 || !/^\d{4}\/\d{4}$/.test(sessionValue)) return UI.toast('Choose a faculty and enter a session like 2026/2027.', 'bad');
      const items = [];
      for (const line of rawItems) {
        const comma = line.lastIndexOf(',');
        if (comma < 1) return UI.toast(`Use “Item name,amount” for: ${line}`, 'bad');
        const name = line.slice(0, comma).trim(), amountText = line.slice(comma + 1).trim(), amount = Number(amountText);
        if (!name || !/^\d+(\.\d{1,2})?$/.test(amountText) || !Number.isFinite(amount) || amount <= 0) return UI.toast(`Check the fee name and positive amount in: ${line}`, 'bad');
        if (items.some((i) => i.name.toLowerCase() === name.toLowerCase())) return UI.toast(`Fee item “${name}” appears more than once.`, 'bad');
        items.push({ name, amount });
      }
      if (!items.length) return UI.toast('Add at least one fee item.', 'bad');
      const duplicate = DB.get('fees').find((f) => f.id !== id && f.facultyId === facultyId && f.session === sessionValue && (Number(f.level || 0) === Number(level || 0)));
      if (duplicate) return UI.toast('A fee structure already exists for that faculty, level and session. Edit it instead.', 'bad');
      const record = { id: id || DB.uid('FE'), facultyId, level, session: sessionValue, items };
      if (id) DB.update('fees', id, record); else DB.insert('fees', record);
      DB.log(me.name, `${id ? 'Updated' : 'Created'} ${sessionValue} fee structure for ${facName(facultyId)} (${level || 'all levels'}), total ${naira(sum(items, 'amount'))}`);
      UI.toast(`Fee structure ${id ? 'updated' : 'created'}.`, 'ok'); finance();
    };

