      const rows = pays.filter((p) => {
        const s = DB.find('students', p.studentId) || {};
        const haystack = `${s.name || ''} ${s.matNo || ''} ${p.reference || ''}`.toLowerCase();
        return (!term || haystack.includes(term)) && (!method || p.method === method) && (!status || p.status === status);
      });
      document.getElementById('payment-rows').innerHTML = rows.length ? rows.map((p) => {
        const s = DB.find('students', p.studentId) || {};
        const tone = p.status === 'confirmed' ? 'ok' : p.status === 'pending' ? 'warn' : 'bad';
        return `<tr><td>${UI.date(p.date)}</td><td>${esc(s.name || 'Unknown student')}<br><span class="muted">${esc(s.matNo || '-')}</span></td><td>${esc(p.method)}</td><td>${esc(p.reference)}</td><td>${UI.badge(p.status || 'confirmed', tone)}${p.status === 'voided' ? `<br><span class="muted">${esc(p.voidReason || '')}</span>` : ''}</td><td class="num">${naira(p.amount)}</td><td><button class="btn btn-ghost btn-sm" data-receipt="${esc(p.id)}">Print receipt</button>${(p.status || 'confirmed') === 'confirmed' && Auth.can('finance:edit', session) ? ` <button class="btn btn-ghost btn-sm" data-void-payment="${esc(p.id)}">Void</button>` : ''}</td></tr>`;
      }).join('') : '<tr><td colspan="7">No payments match these filters.</td></tr>';
      document.getElementById('payment-count').textContent = `Showing ${rows.length} of ${pays.length} payments`;
